        cases.push_back(run_balanced_ledger_case(
            "p1-frame0-21-42-balanced-ledger",
            make_b4b_supported_column_fixture(),
            B4C3Q_P1_SCENARIO_SHA256,
            B4C3_P1_SCENARIO_SHA256, 21));
