    const bool passed = parent_exact && synthetic.passed && real.passed;
    const std::string disposition = passed
        ? "CANONICAL_KKT_SCALE_LEDGER_CANDIDATE"
        : "CANONICAL_KKT_SCALE_LEDGER_REJECTED";
