    "credit=b4ep10-architecture-only";

bool add_phase_duration(
    std::uint64_t value,
    std::uint64_t& sum) {
    if (value > std::numeric_limits<std::uint64_t>::max() - sum) {
        return false;
    }
    sum += value;
    return true;
}

